      ev: { origin: (v, T) => `Origen probable: ${T.origin[v.origin]}.`, evacuation: 'Evacuación de coágulos (sonda de Couvelaire) y lavado continuo.', irrigation: 'Sonda de tres vías con lavado continuo.', transfusion: (v) => `Transfusión de concentrado de hematíes (n.º ${v.n}).`, clotRetention: 'Retención por coágulos.', etiological: 'Tratamiento etiológico del sangrado.' },
      dec: { mild: 'Leve: sin repercusión analítica.', moderate: 'Moderada: descenso de la serie roja (≤ 6 concentrados).', severe: 'Intensa: > 6 concentrados de hematíes.' },
      ref: ['Inicial → uretra o próstata · terminal → vejiga · total → tracto superior.', 'Tira reactiva negativa: no hay hematuria.', 'Coágulos → sonda de Couvelaire + tres vías con lavado continuo.'],
