      tx: 'Extraperitoneal cerrada sin complicaciones: sonda vesical y cistografía antes de retirarla. Intraperitoneal, penetrante o con afectación del cuello vesical: reparación quirúrgica.',
      p: { type: 'Localización', penetrating: 'Penetrante', pelvicFracture: 'Fractura de pelvis' },
