      ev: { catheter: 'Sonda vesical.', surgery: 'Reparación quirúrgica de la vejiga.', peritonitis: 'Peritonitis urinosa.', cystogram: 'Cistografía de control: cerrada, se retira la sonda.', pelvicAbscess: 'Urinoma perivesical infectado.' },
