      ev: { cystostomyDelayed: 'Cistostomía suprapúbica (uretroplastia diferida).', catheter: 'Sonda uretral (lesión parcial).', realignment: 'Realineamiento endoscópico sobre sonda.', immediateRepair: 'Reparación uretral inmediata.', urethroplasty: 'Uretroplastia diferida (3 meses).', urethrogram: 'Uretrografía de control: se retira la sonda.', retention: 'Retención urinaria.', stricture: 'Estenosis uretral establecida.' },
