      s: { pain: 'Pain' },
      st: { subacute: 'Subacute onset, upper-pole pain.', blueDot: '"Blue dot" through the skin.', cremaster: 'Cremasteric reflex present; normal testicular flow.', conservative: 'Rest, NSAIDs and elevation.' },
      ev: { nsaid: 'NSAIDs and rest.' },
      dec: { conservative: 'Conservative treatment: rest and NSAIDs.' },
      ref: ['Appendage: upper pole, blue dot, cremasteric reflex present.'],
