export const I18N = { es, en };
export const LANGS = ['es', 'en'];

/** Resolve a dotted key against a language table; returns undefined if missing. */
export function lookup(lang, path) {
  return path.split('.').reduce((o, k) => (o == null ? undefined : o[k]), I18N[lang]);
}
